tariffs = data['tariff_rates']['data']
trade = data['bilateral_trade']['data']
supply = data['supply_chain_share']['data']
events = data['policy_events']['data']

# We will create a timeline from 2016-H1 to 2024-H2
labels = []
for y in range(2016, 2025):
    labels.append(f"{y}-H1")
    labels.append(f"{y}-H2")

us_tariffs = []
cn_tariffs = []
for l in labels:
    match = next((t for t in tariffs if t['period'] == l), None)
    if match:
        us_tariffs.append(match['us_tariff_on_china'])
        cn_tariffs.append(match['china_tariff_on_us'])
    else:
        us_tariffs.append(None)
        cn_tariffs.append(None)

trade_vol = []
us_export = []
us_import = []
cn_share = []
vn_share = []
in_share = []

for l in labels:
    year = int(l[:4])
    h = l[5:]
    if h == 'H2' or (year == 2024 and h == 'H1'): # Put annual data at the end of the year or available half
        tr_match = next((t for t in trade if t['year'] == year), None)
        if tr_match:
            trade_vol.append(tr_match['total_bilateral'])
        else:
            trade_vol.append(None)

        sp_match = next((s for s in supply if s['year'] == year), None)
        if sp_match:
            cn_share.append(sp_match['china'])
            vn_share.append(sp_match['vietnam'])
            in_share.append(sp_match['india'])
        else:
            cn_share.append(None)
            vn_share.append(None)
            in_share.append(None)
    else:
        trade_vol.append(None)
        cn_share.append(None)
        vn_share.append(None)
        in_share.append(None)

# Let's map events to indices
event_annotations = []
for i, l in enumerate(labels):
    evs = [e for e in events if e['period_approx'] == l]
    if evs:
        # combine events
        titles = [e['event'] for e in evs]
        event_annotations.append({"index": i, "label": l, "events": titles})

